      section: "形容词副词",
      stem: "Shanghai is bigger than in Australia.",
      options: ["any city","any cities","any other city","any other cities"],
      answer: "A",
      pitfalls: ["不属同一范围，用 than any + 单数","同范围才用 any other"],
      hint: "【结论】A 【考点】比较范围 【一步步怎么算】上海比澳大利亚任何城市都大，用 any city（上海不在澳大利亚，不加 other）。 故答案为 A。",
      analysis: "【审题】题干：Shanghai is bigger than in Australia。本句考查比较范围。\n【语法点/词汇】形容词修饰名词，副词修饰动词/形容词/副词（good 修饰 habit，well 修饰 eats）。比较级+than，最高级用于三者及以上；one of the + 最高级 + 名词复数。修饰比较级用 much/far/even/a little/any，不能用 very。比较级要避免比较 more 本身（more enjoyable 用 much/far 修饰）。enough 修饰形容词/副词后置（good enough、well enough），修饰名词可前置。too...to（太…而不能），so...that / such...that（如此…以至于）。the + 比较级..., the + 比较级...（越…越…）。population 用 large/small 修饰，比较对象用 that 指代。比较对象要一致（in my garden 用 in mine）。形容词修饰不定代词后置（anything cheap）。lively（生动的、活泼的）、alive（活着的，表语）、live（现场直播的；动词）。复合形容词 a three-day holiday（用单数）。比较\"不在同一范围\"用 than any other + 单数；\"不在该范围\"用 than any + 单数。\n【步骤】① 定位考点：比较范围。② 上海比澳大利亚任何城市都大，用 any city（上海不在澳大利亚，不加 other）。 ③ 由此确定答案为 A。\n【答案】A. any city\n【易错】不属同一范围，用 than any + 单数；同范围才用 any other。\n【口诀/模板句】形修名副修动；enough 后置；much/far 修比较；the more...the more；比较对象要一致；不在范围不加 other。"
