      analysis: "【审题】题干：Sam and Henry play football very well. We hope of them can join our team。本句考查both 两者都。\n【语法点/词汇】both（两者都）、neither（两者都不）、either（两者任一）、all（三者以上都）、none（三者以上都不）。each 强调个体、可接 of、谓语单数；every 强调整体、不能接 of。another（另一个，泛指）、the other（两者中另一个）、others（别的）、the others（其余全部）。it 作形式主语/宾语：find/make it + 形容词 + to do。物主代词：形容词性（my/your/his/her/our/their）后接名词，名词性（mine/yours/his/hers/ours/theirs）单独用。反身代词 enjoy oneself/teach oneself/by oneself，与主语一致。疑问代词 who（主格）、whom（宾格）、whose（谁的）；what else 还有什么。人称代词排序：单数 you, he and I（第二、三、一）。both 在句中位于 be 动词后、实义动词前。\n【步骤】① 定位考点：both 两者都。② Sam 和 Henry 两人，希望\"两个都\"加入，用 both。 ③ 由此确定答案为 B。\n【答案】B. both\n【易错】两个人用 both；all 用于三者以上。\n【口诀/模板句】both 都 neither 都不 either 任一；each 接 of every 不接；形物后加名，名物单独用；it 形主形宾；反身代词看主语。"
