      analysis: "【审题】题干：Mr White rarely shares his opinions with his workmates. ?。本句考查rarely 否定。\n【语法点/词汇】陈述部分用肯定，疑问用否定；陈述部分用否定（含 never/hardly/rarely/few/little/nothing/no one 等否定词），疑问用肯定。时态、人称、助动词与陈述部分一致。there be 句型用 be there。否定/半否定词：hardly、rarely、few、little、nothing、never 都算否定。祈使句的反意疑问一般用 will you/won't you。否定疑问句的回答要按事实：事实是肯定用 Yes，否定用 No。\n【步骤】① 定位考点：rarely 否定。② rarely shares（否定，实义动词），疑问用 does he。 ③ 由此确定答案为 A。\n【答案】A. does he\n【易错】rarely 否定；三单借助 does。\n【口诀/模板句】前肯后否，前否后肯；hardly/few/little 算否定；there be 用 there；回答看事实，事实肯定用 Yes。"
