      analysis: "【审题】题干：The story is interesting I can't stop laughing。本句考查so...that。\n【语法点/词汇】时间：when、while、as（当…时）、as soon as（一…就）、not...until（直到…才）、before/after。条件：if（如果）、unless（除非）、as long as（只要）。让步：though/although（虽然）、even if（即使）、however（无论怎样）、no matter + 疑问词、whatever/whoever/whenever。目的：so that（以便）、in order that。结果：so...that（如此…以至于）。as far as I know（据我所知）。when 引导瞬间动作用一般过去时；while 引导持续性动作。\n【步骤】① 定位考点：so...that。② 如此有趣以至于，interesting 形容词用 so; that。 ③ 由此确定答案为 A。\n【答案】A. so; that\n【易错】so + 形容词 + that。\n【口诀/模板句】as soon as 一…就；unless 除非；as long as 只要；though 虽然；however 无论；so that 以便；as far as I know 据我所知。"
