      analysis: "【考点】“be of + 抽象名词”结构。该结构表示“具有某种性质或特征”，相当于 be + 该名词对应的形容词。\n\n【结构】be of great value = be very valuable（很有价值）；类似的还有 be of importance = be important（重要）、be of help = be helpful（有帮助）、be of use = be useful（有用）。\n\n【步骤】\n① 句意为“这本书很有价值，对我帮助很大”；\n② great value 是抽象名词，要表达“有价值”用 be of value；\n③ 故选 D。\n\n【答案】D。\n\n【口诀】of 加抽象名词，等于对应形容词：of value = valuable。",
