      analysis: "【考点】年龄表达与零冠词。\n\n【规则】“主语 + be + 基数词 + years old”表示“某人多少岁”，数词前不加任何介词或冠词。如 She is eighteen years old.（她十八岁）。\n\n【辨析】at eighteen 也可表示“在十八岁时”，但要说 She is at eighteen 不符合“is + 年龄 + years old”的结构。\n\n【步骤】\n① 句子结构为 She is … eighteen years old；\n② 此结构中数词前不加介词，用零冠词；\n③ 选 D（/）。\n\n【答案】D。\n\n【口诀】be + 数字 + years old，中间零冠词。",
      difficulty: 1
