      analysis: "【考点】延续性动词与“for + 时间段”连用。\n\n【规则】for three hours 表示持续了一段时间，要求谓语动词或状态是可延续的。leave（离开）是短暂/非延续性动词，不能与表示一段时间的 for 短语连用；be away（离开的状态）是可延续的，可用 has been away。\n\n【转换】短暂动词 → 延续状态：leave → be away；buy → have；borrow → keep；die → be dead；join → be in/be a member。\n\n【步骤】\n① for three hours 表持续，排除短暂动词 leave 相关的 A、C；\n② 用可延续的 be away，现在完成时 has been away；\n③ 选 B。\n\n【答案】B。\n\n【口诀】for + 时间段配延续，leave 要换成 be away。",
      difficulty: 1
