              "passage": "Most of us know about fires, hurricanes, droughts and floods. But from time to time, Mother Nature surprises us, and delivers a weather event that is really weird. Here are some examples of truly strange weather.\n\nOne day in 2005, residents of a small town in Serbia looked out of their windows and saw an unusual sight. It was raining frogs! Without any warning, they found their streets filled with little jumping creatures. \"There were thousands of them,\" one resident told a local newspaper. \"I thought perhaps a plane carrying frogs had exploded,\" said another. Scientists believed a tornado had passed over a lake. It sucked up animals that lived there. The frogs were carried into the air. Then they were dropped in the Serbian town, far away.\n\nAs if tornadoes aren't dangerous enough, some of them can actually be made of fire. When a wildfire reaches very high temperatures, it causes the air to become hot and to rise. Cooler air rushes in to replace the hot air. This creates strong winds. These winds suck up burning plants and even the fire itself. When this happens, as it did on March 14, 2014, in Denver, Colorado, a tornado of fire is produced. This tornado can become 15 meters (50 feet) wide and grow as tall as a 40-story building.\n\nIn 1942, hundreds of thousand-year-old skeletons were found under the ice of Lake Roopkund in the Himalayas. Many had holes in their skulls. But they weren't hurt in any other way. Scientists thought the people must have been hit from above. But for years, the cause of their deaths was a mystery. Today, scientists think these people were killed by giant hailstones — balls of ice. Hailstones form when raindrops high in the sky turn into pieces of ice. The ice pieces increase in size until the wind cannot hold them up. This results in hailstones falling to the ground, often at speeds of over 160 kilometers (100 miles) an hour. For the unlucky people at Lake Roopkund, there was nowhere to run. They were all killed by the hailstones.",
